public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int n = scanner.nextInt();

    String gridA[][] = new String[n][];
    String gridB[][] = new String[n][];
    int row = 0;
    int column = 0;

    for (int i = 0; i < n; i++) {
        String text = scanner.next();
        gridA[i] = text.split("");
    }

    for (int i = 0; i < n; i++) {
        String text = scanner.next();
        gridB[i] = text.split("");
    }

    scanner.close();

    outerLoop:
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!gridA[i][j].equals(gridB[i][j])) {
                row = i + 1;
                column = j + 1;
                break outerLoop;
            }
        }
    }

    System.out.println(row + " " + column);
}
